import React, { useState } from 'react'
import axiosInstance from '../api/axiosInstance'

export function AdminDashboard() {
    const [name, setName] = useState('')
    const [startDate, setStartDate] = useState('')
    const [endDate, setEndDate] = useState('')
    const [status, setStatus] = useState('Upcoming')
    const [tournament, setTournament] = useState('')
    const [addTeam, setAddTeam] = useState('')
    const [tournamentId, setTournamentId] = useState('')
    const [teamId, setTeamId] = useState('')
    const [teamA, setTeamA] = useState('')
    const [teamB, setTeamB] = useState('')
    const [venue, setVenue] = useState('')
    const [matchDate, setMatchDate] = useState('')
    const [matchTournament, setMatchTournament] = useState('')
    const [match, setMatch] = useState('')
    const [updateMatch,setUpdateMatch]=useState('')
    const [winner,setWinner]=useState("")
    const [result,setResult]=useState("")
        async function handleCreateTournament(e) {
        e.preventDefault()
        try {
            const response = await axiosInstance.post('/tournament/create', { name, startDate, endDate, status })
            setTournament(response.data)

        }
        catch (error) {
            console.log(error);

        }
    }
    async function addTeamToTournament(e) {
        e.preventDefault()
        try {
            const response = await axiosInstance.put('/tournament/addteam/' + tournamentId, { teamId })
            setAddTeam(response.data)

        } catch (error) {
            console.log(error);

        }
    }
    async function sheduleMatch(e) {
        e.preventDefault()
        try {
            const response = await axiosInstance.post('/match/create', { tournament: matchTournament, teamA, teamB, venue, matchDate })
            setMatch(response.data)
        }
        catch (error) {
            console.log(error);

        }

    }

    async function updateMatchResult(e) {
        e.preventDefault()
        try {
            const response = await axiosInstance.post('/match/updatematch'+matchId,{winner,result})
            setUpdateMatch(response.data)
        } catch (error) {
            console.log(error);x``

        }

    }
    return (
        <div><h1>AdminDashboard</h1>
            <form onSubmit={handleCreateTournament}>
                <div>
                    <label>Tournament Name</label>
                    <input type="text" value={name} onChange={(e) => { setName(e.target.value) }} />
                </div>
                <div>
                    <label>Stard Date</label>
                    <input type="date" value={startDate} onChange={(e) => { setStartDate(e.target.value) }} />
                </div>
                <div>
                    <label>End Date</label>
                    <input type="date" value={endDate} onChange={(e) => { setEndDate(e.target.value) }} />
                </div>
                <button>Submit</button>
            </form>

            <div>
                <form onSubmit={addTeamToTournament}>
                    <div><label>Tournament Id</label>
                        <input type="text" value={tournamentId} onChange={(e) => { setTournamentId(e.target.value) }} /></div>
                    <div><label>TeamId</label>
                        <input type="text" value={teamId} onChange={(e) => { setTeamId(e.target.value) }} /></div>
                    <button>Add</button>
                </form>
            </div>

            <div>
                <form onSubmit={sheduleMatch}>
                    <div>
                        <label>Tournament</label>
                        <input type="text" value={matchTournament} onChange={(e) => { setMatchTournament(e.target.value) }} />
                    </div>
                    <div>
                        <label>Team A</label>
                        <input type="text" value={teamA} onChange={(e) => { setTeamA(e.target.value) }} />
                    </div>
                    <div>
                        <label>Team B</label>
                        <input type="text" value={teamB} onChange={(e) => { setTeamB(e.target.value) }} />
                    </div>
                    <div>
                        <label>Venue</label>
                        <input type="text" value={venue} onChange={(e) => { setVenue(e.target.value) }} />
                    </div>
                    <div>
                        <label>Match date</label>
                        <input type="date" value={matchDate} onChange={(e) => { setMatchDate(e.target.value) }} />
                    </div>
                    <button>submit</button>
                </form>
            </div>
            <div>
                <form onSubmit={updateMatch}>
                    <div><label>Winner</label>
                    <input type="text" value={winner} onChange={(e)=>{setWinner(e.target.value)}} /></div>
                    <div><label>Result</label>
                    <input type="text" value={result} onChange={(e)=>{setResult(e.target.value)}} /></div>
                    <button></button>
                </form>
            </div>
        </div>
    )
}
